    font-size: 14px;
    line-height: 1.8;
    white-space: pre-wrap;
}
.buff-info:empty::after {
    content: "无激活BUFF";
    color: #888888;
    font-style: italic;
}
</style>
</head>
<body>

<div class="main-container">
    <!-- 导航按钮 -->
    <div class="nav-buttons">
        <button class="nav-btn active" onclick="showPage(1)" id="nav-1">
            <span>📜</span>
            <span>对话</span>
        </button>
        <button class="nav-btn" onclick="showPage(2)" id="nav-2">
            <span>🗺️</span>
            <span>地图</span>
        </button>
        <button class="nav-btn" onclick="showPage(3)" id="nav-3">
            <span>⚔️</span>
            <span>状态</span>
        </button>
    </div>

    <!-- 页面1：对话 -->
    <div id="page-1" class="page active">
        <div class="dialog-box">
            <div class="dialog-header">系统文档</div>
            <div class="dialog-content">$1</div>
            <div class="dialog-footer">
                <div class="dialog-seal">灵</div>
                <div class="dialog-date">$30</div>
            </div>
        </div>
    </div>

    <!-- 页面2：地图 -->
<div id="page-2" class="page">
    <div class="map-header">
        <div class="map-title">
            <span>🗺️</span>
            <span>灵纪元世界地图</span>
        </div>
    </div>

    <div class="continent-info">
        <div class="continent-status">
            <span>🌏</span>
            <span>世界概况</span>
            <span style="margin-left: auto; font-size: 12px; color: #00d4ff;">$30</span>
        </div>
        <div class="continent-details">
            五大陆格局：中央大陆（华夏大陆）、西南大陆（矿产大陆）、妖域一重（缓冲大陆）、妖域二重（孤岛大陆）、妖域三重（极境大陆）
            <br>总面积：约4400万平方公里 | 人类控制区：约2600万平方公里 | 妖域面积：约2800万平方公里
        </div>
    </div>

    <!-- 大陆分布总览 -->
    <div class="map-overview">
        <pre style="color: #00d4ff; text-align: center; font-family: monospace;">
       北
       ↑
   [妖域二重]
       |
[妖域一重]--[中央大陆]
    |         |
[妖域三重]--[西南大陆]
        </pre>
    </div>

    <!-- 位置信息 -->
    <div class="location-info">
        <div class="current-location">当前位置：$31</div>
        <div class="available-locations">可前往：$32</div>
        <div class="available-actions">可选行动：$33</div>
    </div>

    <div class="continent-grid">
        <div class="continent-card" onclick="toggleZone('central')">
            <div class="continent-name">中央大陆</div>
            <div class="continent-subtitle">华夏大陆</div>
            <div class="continent-size">约1800万平方公里</div>
            <div class="continent-hint">▶ 点击展开</div>
        </div>

        <div class="continent-card" onclick="toggleZone('southwest')">
            <div class="continent-name">西南大陆</div>
            <div class="continent-subtitle">矿产大陆</div>
            <div class="continent-size">约800万平方公里</div>
            <div class="continent-hint">▶ 点击展开</div>
        </div>

        <div class="continent-card" onclick="toggleZone('demon1')">
            <div class="continent-name">妖域一重</div>
            <div class="continent-subtitle">缓冲大陆</div>
            <div class="continent-size">约1200万平方公里</div>
            <div class="continent-hint">▶ 点击展开</div>
        </div>

        <div class="continent-card" onclick="toggleZone('demon2')">
            <div class="continent-name">妖域二重</div>
            <div class="continent-subtitle">孤岛大陆</div>
            <div class="continent-size">约600万平方公里</div>
            <div class="continent-hint">▶ 点击展开</div>
        </div>

        <div class="continent-card" onclick="toggleZone('demon3')">
            <div class="continent-name">妖域三重</div>
            <div class="continent-subtitle">极境大陆</div>
            <div class="continent-size">约1000万平方公里</div>
            <div class="continent-hint">▶ 点击展开</div>
        </div>
    </div>

    <!-- 区域详情 -->
    <div id="central-zone" class="zone-details">
        <div class="zone-title">中央大陆（华夏大陆）</div>
        <div class="zone-item">
            <div class="zone-item-title">面积</div>
            <div class="zone-item-desc">约1800万平方公里（最大）</div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">形状</div>
            <div class="zone-item-desc">如展翅凤凰，东西横长</div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">地形特征</div>
            <div class="zone-item-desc">
                中部平原广袤，江河纵横<br>
                东部沿海富饶，港口密布<br>
                西部高原屏障，易守难攻<br>
                南北山脉环绕，气候宜人
            </div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">核心城市</div>
            <div class="zone-item-desc">长安位于大陆心脏地带</div>
        </div>

        <!-- 大唐长安详情 -->
        <div class="city-section">
            <div class="city-header">大唐长安 - 天空之都</div>
            <div class="city-info">
                <div class="city-stats">
                    总面积：约800平方公里（悬浮主体）+ 200平方公里（地面辅助区）<br>
                    悬浮高度：距地面800-1200米，分三层悬浮<br>
                    常住人口：约500万（流动人口100-150万）<br>
                    常驻种族：全种族混居，以人类为主（50%）
                </div>

                <div class="district-grid">
                    <div class="district-item">
                        <div class="district-name">一、核心区（最高层，50平方公里）</div>
                        <div class="district-desc">
                            位置：城市最高处，云端之上<br>
                            特征：<br>
                            - 皇城：占地15平方公里，九重宫阙，灵光护罩常年笼罩<br>
                            - 天枢阁：帝国最高决策机构<br>
                            - 兵备司：禁卫军驻地，约3000人精锐<br>
                            - 灵能中枢：为全城供能的巨型灵石阵眼
                        </div>
                    </div>

                    <div class="district-item">
                        <div class="district-name">二、天工区（中层西部，120平方公里）</div>
                        <div class="district-desc">
                            位置：悬浮中层，灵力管网密集<br>
                            特征：<br>
                            - 天工府：帝国科技研发总部，占地30平方公里<br>
                            - 锻造区：上千家私人工坊与大型企业<br>
                            - 灵机研究中心：专门研制灵机模组<br>
                            - 药王谷分部：各类丹药炼制与销售
                        </div>
                    </div>

                    <div class="district-item">
                        <div class="district-name">三、学府区（中层东部，100平方公里）</div>
                        <div class="district-desc">
                            位置：环境清幽，灵气充沛<br>
                            特征：<br>
                            - 天安学府主院：容纳百万学子的超级学府<br>
                            - 研究院：研究制造灵机以及灵机模组<br>
                            - 演武场：可容纳十万人观战<br>
                            - 学舍群：按年级与专业分布的悬浮建筑群
                        </div>
                    </div>

                    <div class="district-item">
                        <div class="district-name">四、贵族区（中层北部，150平方公里）</div>
                        <div class="district-desc">
                            位置：视野最佳，俯瞰全城<br>
                            特征：<br>
                            - 豪门大宅：独立悬浮的私人领地<br>
                            - 天香阁：顶级青楼，歌舞升平<br>
                            - 凯拉机斗场：帝国最大的灵机竞技场（设施健全，防护高，竞技场防护连天阶灵机神全力都无法攻破）<br>
                            - 望月楼：十二层高楼，美食与情报中心<br>
                            - 万宝拍卖行：每月一次的顶级拍卖（十层高楼，楼顶专拍卖机甲）
                        </div>
                    </div>

                    <div class="district-item">
                        <div class="district-name">五、居民区（下层主体，280平方公里）</div>
                        <div class="district-desc">
                            位置：最大的生活区域<br>
                            特征：<br>
                            - 长安广场：可容纳百万人的巨型广场<br>
                            - 美食街：东街川菜、西街粤菜、南街异域风味<br>
                            - 百业坊：各类店铺超过十万家<br>
                            - 宗教区：三教九流，诸神共存<br>
                            - 黑市：午夜开启的地下交易网络
                        </div>
                    </div>

                    <div class="district-item">
                        <div class="district-name">六、海港区（地面区域，100平方公里）</div>
                        <div class="district-desc">
                            位置：地面沿海，与悬浮城市有升降梯连接<br>
                            特征：<br>
                            - 灵力码头：二十座大型泊位<br>
                            - 飞空港：空中舰队停泊地<br>
                            - 货运中心：日吞吐量惊人<br>
                            - 异族商馆：各国商人聚集地<br>
                            - 商城区：不同贸易类型的企业聚集地
                        </div>
                    </div>
                </div>
            </div>
        </div>

        <!-- 其他城市 -->
        <div class="zone-item">
            <div class="zone-item-title">英格兰城 - 雾都要塞</div>
            <div class="zone-item-desc">
                城市规模：<br>
                总面积：约200平方公里<br>
                城墙高度：50米高的灵力屏障<br>
                常住人口：约150万<br>
                常驻种族：人类60%、精灵25%、其他15%<br><br>

                区域布局：<br>
                一、骑士区（北部，40平方公里）<br>
                - 圆桌议事厅：仿古圆形建筑<br>
                - 骑士团驻地：十二骑士团总部<br>
                - 决斗场：骑士荣誉之战场地<br>
                - 贵族庄园群<br><br>

                二、工匠区（东部，60平方公里）<br>
                - 蒸汽工坊街：灵力蒸汽混合动力<br>
                - 炼金术士塔：三座高塔<br>
                - 机械市集：各类灵机零件<br>
                - 学徒公寓区<br><br>

                三、贸易区（南部，100平方公里）<br>
                - 泰晤士大市场：占地20平方公里<br>
                - 金融街：钱庄与商会林立<br>
                - 酒馆一条街：情报交换中心<br>
                - 平民住宅区
            </div>
        </div>

        <div class="zone-item">
            <div class="zone-item-title">法兰西城 - 浪漫之都</div>
            <div class="zone-item-desc">
                城市规模：<br>
                总面积：约180平方公里<br>
                特色：灵力喷泉遍布全城<br>
                常住人口：约120万<br>
                常驻种族：人类50%、精灵30%、龙裔10%、其他10%<br><br>

                区域布局：<br>
                一、艺术区（中心区，50平方公里）<br>
                - 凡尔赛宫：城主府邸<br>
                - 卢浮宫：帝国艺术珍藏馆<br>
                - 歌剧院：每夜上演灵力幻境剧<br>
                - 艺术家工坊街<br><br>

                二、贵族区（西部，60平方公里）<br>
                - 香榭大道：宽百米的林荫道<br>
                - 玫瑰庄园群：各大家族领地<br>
                - 决斗俱乐部：贵族社交中心<br>
                - 高级时装街<br><br>

                三、学者区（东部，70平方公里）<br>
                - 巴黎学院：专攻灵力理论<br>
                - 哲学家广场：思想交流地<br>
                - 古籍书店街<br>
                - 学生公寓区
            </div>
        </div>

        <div class="zone-item">
            <div class="zone-item-title">希腊城 - 神话古城</div>
            <div class="zone-item-desc">
                城市规模：<br>
                总面积：约150平方公里<br>
                特色：保留大量上古遗迹<br>
                常住人口：约80万<br>
                常驻种族：人类70%、其他30%<br><br>

                区域布局：<br>
                一、神殿区（山顶区，30平方公里）<br>
                - 帕特农神殿：供奉诸神<br>
                - 祭司居所<br>
                - 圣泉<br><br>

                二、竞技区（山腰区，50平方公里）<br>
                - 奥林匹斯竞技场：可容5万人<br>
                - 角斗士训练营<br>
                - 英雄纪念馆<br>
                - 战士公寓<br><br>

                三、港口区（海滨区，70平方公里）<br>
                - 比雷埃夫斯港：地中海式港口<br>
                - 海商会馆<br>
                - 渔人码头<br>
                - 海神庙
            </div>
        </div>

        <div class="zone-item">
            <div class="zone-item-title">印度城 - 香料之城</div>
            <div class="zone-item-desc">
                城市规模：<br>
                总面积：约160平方公里<br>
                特色：灵兽与人类共生<br>
                常住人口：约100万<br>
                常驻种族：人类60%、兽人20%、其他20%<br><br>

                区域布局：<br>
                一、王宫区（中心区，40平方公里）<br>
                - 泰姬陵式宫殿群<br>
                - 皇家灵兽园<br>
                - 贵族府邸<br>
                - 禁卫军营<br><br>

                二、市集区（南部，70平方公里）<br>
                - 香料大市场：异香扑鼻<br>
                - 宝石街：各类灵石加工<br>
                - 布料染坊区<br>
                - 平民社区<br><br>

                三、寺庙区（北部，50平方公里）<br>
                - 千佛寺：供奉各路神明<br>
                - 苦行者聚居地<br>
                - 瑜伽修炼场<br>
                - 朝圣者客栈
            </div>
        </div>

        <div class="zone-item">
            <div class="zone-item-title">东瀛城 - 樱海之城</div>
            <div class="zone-item-desc">
                城市规模：<br>
                总面积：约140平方公里<br>
                特色：四季樱花不败（灵力维持）<br>
                常住人口：约90万<br>
                常驻种族：人类40%、其他60%<br><br>

                区域布局：<br>
                一、武士区（东部，40平方公里）<br>
                - 幕府城：城主居所<br>
                - 道场街：上百家剑道场<br>
                - 武士长屋<br>
                - 演武场<br><br>

                二、町人区（中部，60平方公里）<br>
                - 浅草寺：最大寺院<br>
                - 花街：艺伎表演区<br>
                - 居酒屋街<br>
                - 工匠作坊<br><br>

                三、港町区（西部临海，40平方公里）<br>
                - 横滨港：对外贸易港<br>
                - 鱼市场：清晨最热闹<br>
                - 海人村：渔民聚居<br>
                - 灯塔与海关
            </div>
        </div>

        <!-- 中央大陆城市位置图 -->
        <div class="zone-item">
            <div class="zone-item-title">中央大陆城市位置图</div>
            <div class="zone-item-desc">
                <pre style="font-family: monospace;">
     [北部旷野山脉区 - 约400万平方公里]
           ↓
[西部高原旷野] --- [核心文明区] --- [东部沿海旷野]
 300万km²         800万km²         200万km²
           ↑
     [南部密林旷野区 - 约300万平方公里]
                </pre>
            </div>
        </div>

        <div class="zone-item">
            <div class="zone-item-title">中央大陆旷野区详情</div>
            <div class="zone-item-desc">
                旷野区分布：<br>
                - 北部旷野（400万km²）：雪山连绵，雪域妖兽出没<br>
                - 西部旷野（300万km²）：戈壁草原，游牧妖兽群<br>
                - 东部旷野（200万km²）：沼泽密林，毒虫猛兽<br>
                - 南部旷野（300万km²）：原始雨林，妖王领地
            </div>
        </div>
    </div>

    <div id="southwest-zone" class="zone-details">
        <div class="zone-title">西南大陆（矿产大陆）</div>
        <div class="zone-item">
            <div class="zone-item-title">面积</div>
            <div class="zone-item-desc">约800万平方公里</div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">形状</div>
            <div class="zone-item-desc">似弯月刀刃，南北纵长</div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">地形特征</div>
            <div class="zone-item-desc">
                60%为沙漠戈壁<br>
                北部绿洲点缀，城邦林立<br>
                中部矿脉纵横，资源丰富<br>
                南部沿海狭长，贸易繁荣
            </div>
        </div>
        <div class="zone-item">
            <div class="zone-item-title">特色</div>
            <div class="zone-item-desc">地下矿藏极其丰富，尤以灵石矿脉著称</div>
        </div>

        <!-- 沙罗帝国 -->
        <div class="zone-item">
            <div class="zone-item-title">沙罗帝国 - 沙漠霸主</div>
            <div class="zone-item-desc">
                国家规模：<br>
                领土面积：约300万平方公里（西南大陆北部）<br>
                首都：巴比伦城（绿洲中的奇迹）<br>
                人口：约2000万<br>
                特色：控制主要灵石矿脉，极度富裕<br><br>

                首都布局：<br>
                - 皇宫区：金字塔形巨型宫殿<br>
                - 商业区：驼队贸易中心<br>
                - 矿工区：各大矿业公司总部
            </div>
        </div>

        <!-- 月神联邦 -->
        <div class="zone-item">
            <div class="zone-item-title">月神联邦 - 绿洲同盟</div>
            <div class="zone-item-desc">
                国家规模：<br>
                领土面积：约200万平方公里（西南大陆南部）<br>
                首都：新月城（沿海贸易港）<br>
                人口：约1500万<br>
                特色：七个绿洲城邦的松散联盟<br><br>

                首都布局：<br>
                - 议会区：七邦代表议事厅<br>
                - 贸易区：海陆贸易枢纽<br>
                - 使馆区：各邦代表处
            </div>
        </div>

        <!-- 其余小城邦 -->
        <div class="zone-item">
            <div class="zone-item-title">其余小城邦（约30个）</div>
            <div class="zone-item-desc">
                分布在两大国之间的缓冲地带，各有数万到数十万人口，依附于两大国生存，主要从事：<br>
                - 商队护送<br>
                - 小型矿场开采<br>
