<script>
// 页面切换
function showPage(pageNum) {
    // 隐藏所有页面
    const pages = document.querySelectorAll('.page');
    pages.forEach(page => page.classList.remove('active'));

    // 显示选中的页面
    document.getElementById('page-' + pageNum).classList.add('active');

    // 更新导航按钮状态
    const navBtns = document.querySelectorAll('.nav-btn');
    navBtns.forEach(btn => btn.classList.remove('active'));
    document.getElementById('nav-' + pageNum).classList.add('active');
}

// Tab切换
function showTab(tabNum) {
    // 隐藏所有tab内容
    const tabs = document.querySelectorAll('.tab-content');
    tabs.forEach(tab => tab.classList.remove('active'));

    // 显示选中的tab
    document.getElementById('tab-content-' + tabNum).classList.add('active');

    // 更新tab按钮状态
    const tabBtns = document.querySelectorAll('.tab-btn');
    tabBtns.forEach(btn => btn.classList.remove('active'));
    document.getElementById('tab-' + tabNum).classList.add('active');

    // 如果切换到属性分配页面，重绘雷达图
    if (tabNum === 2) {
        setTimeout(drawRadarChart, 100);
    }
}

// 区域展开/收起
function toggleZone(zoneName) {
    const zone = document.getElementById(zoneName + '-zone');
    const allZones = document.querySelectorAll('.zone-details');

    // 先关闭所有区域
    allZones.forEach(z => {
        if (z !== zone) {
            z.classList.remove('active');
        }
    });

    // 切换当前区域
    zone.classList.toggle('active');
}

// 属性分配系统
let originalAttrs = {
    int: parseInt('$18') || 0,
    qi: parseInt('$19') || 0,
    agi: parseInt('$20') || 0,
    ac: parseInt('$21') || 0
};

let currentAttrs = {...originalAttrs};
let remainingPoints = parseInt('$17') || 0;

// 属性评价系统
function getIntEvaluation(value) {
    if (value <= 2) return "虚弱无力";
    if (value <= 5) return "凡人之躯";
    if (value <= 8) return "强壮有力";
    if (value <= 11) return "人间勇士";
    if (value <= 14) return "超凡之力";
    if (value <= 17) return "巨人之握";
    return "神话降临";
}

function getQiEvaluation(value) {
    if (value === 0) return "凡人无气";
    if (value <= 2) return "气感初现";
    if (value <= 5) return "真气萌芽";
    if (value <= 8) return "气海初成";
    if (value <= 11) return "真元浑厚";
    if (value <= 14) return "气贯长虹";
    if (value <= 17) return "天地同寿";
    return "混元归一";
}

function getAgiEvaluation(value) {
    if (value === 0) return "迟缓笨拙";
    if (value <= 2) return "普通反应";
    if (value <= 5) return "身手敏捷";
    if (value <= 8) return "疾如闪电";
    if (value <= 11) return "鬼魅身法";
    if (value <= 14) return "瞬息万变";
    return "时空掌控";
}

function getAcEvaluation(value) {
    if (value === 0) return "毫无防备";
    if (value <= 2) return "基础防护";
    if (value <= 5) return "娴熟守护";
    if (value <= 8) return "钢铁壁垒";
    if (value <= 11) return "不破金身";
    if (value <= 14) return "神话守护";
    return "绝对领域";
}

function changeAttr(attr, delta) {
    if (delta > 0 && remainingPoints <= 0) return;
    if (delta < 0 && currentAttrs[attr] <= originalAttrs[attr]) return;

    currentAttrs[attr] += delta;
    remainingPoints -= delta;

    updateDisplay();
}

function updateDisplay() {
    document.getElementById('int-value').textContent = currentAttrs.int;
    document.getElementById('qi-value').textContent = currentAttrs.qi;
    document.getElementById('agi-value').textContent = currentAttrs.agi;
    document.getElementById('ac-value').textContent = currentAttrs.ac;
    document.getElementById('remaining-points').textContent = remainingPoints;

    // 更新属性评价
    document.getElementById('int-eval').textContent = getIntEvaluation(currentAttrs.int);
    document.getElementById('qi-eval').textContent = getQiEvaluation(currentAttrs.qi);
    document.getElementById('agi-eval').textContent = getAgiEvaluation(currentAttrs.agi);
    document.getElementById('ac-eval').textContent = getAcEvaluation(currentAttrs.ac);

    // 更新按钮状态
    updateButtonStates();

    // 生成指令
    generateCommand();

    // 更新雷达图
    drawRadarChart();
}

function updateButtonStates() {
    const buttons = document.querySelectorAll('.attr-btn');
    buttons.forEach(btn => {
        btn.disabled = false;
    });

    // 禁用减号按钮（如果已经是原始值）
    if (currentAttrs.int <= originalAttrs.int) {
        document.querySelector('[onclick="changeAttr(\'int\', -1)"]').disabled = true;
    }
    if (currentAttrs.qi <= originalAttrs.qi) {
        document.querySelector('[onclick="changeAttr(\'qi\', -1)"]').disabled = true;
    }
    if (currentAttrs.agi <= originalAttrs.agi) {
        document.querySelector('[onclick="changeAttr(\'agi\', -1)"]').disabled = true;
    }
    if (currentAttrs.ac <= originalAttrs.ac) {
        document.querySelector('[onclick="changeAttr(\'ac\', -1)"]').disabled = true;
    }

    // 禁用加号按钮（如果没有剩余点数）
    if (remainingPoints <= 0) {
        document.querySelectorAll('[onclick*="1)"]').forEach(btn => {
            if (btn.textContent === '+') {
                btn.disabled = true;
            }
        });
    }
}

function generateCommand() {
    let commands = [];

    const intDiff = currentAttrs.int - originalAttrs.int;
    const qiDiff = currentAttrs.qi - originalAttrs.qi;
    const agiDiff = currentAttrs.agi - originalAttrs.agi;
    const acDiff = currentAttrs.ac - originalAttrs.ac;

    if (intDiff > 0) commands.push(`意志+${intDiff}`);
    if (qiDiff > 0) commands.push(`灵力+${qiDiff}`);
    if (agiDiff > 0) commands.push(`敏捷+${agiDiff}`);
    if (acDiff > 0) commands.push(`护甲+${acDiff}`);

    const commandText = commands.length > 0 ? 
        `属性分配：${commands.join('，')}` : 
        '未分配任何属性点';

    document.getElementById('command-output').value = commandText;
}

function copyCommand() {
    const textarea = document.getElementById('command-output');
    textarea.select();
    document.execCommand('copy');

    // 视觉反馈
    const btn = event.target;
    const originalText = btn.textContent;
    btn.textContent = '已复制!';
    btn.style.background = 'linear-gradient(135deg, rgba(0,255,0,0.3) 0%, rgba(0,255,0,0.2) 100%)';

    setTimeout(() => {
        btn.textContent = originalText;
        btn.style.background = '';
    }, 1000);
}

function resetAttrs() {
    currentAttrs = {...originalAttrs};
    remainingPoints = parseInt('$17') || 0;
    updateDisplay();
}

// 绘制四维雷达图
function drawRadarChart() {
    const canvas = document.getElementById('radarChart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 100;

    // 清空画布
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 属性名称和值
    const attributes = [
        { name: '意志', value: currentAttrs.int, max: 70 },
        { name: '灵力', value: currentAttrs.qi, max: 70 },
        { name: '敏捷', value: currentAttrs.agi, max: 70 },
        { name: '护甲', value: currentAttrs.ac, max: 70 }
    ];

    // 绘制背景网格
    ctx.strokeStyle = 'rgba(0, 212, 255, 0.2)';
    ctx.lineWidth = 1;

    // 绘制同心多边形
    for (let i = 1; i <= 5; i++) {
        ctx.beginPath();
        for (let j = 0; j < 4; j++) {
            const angle = (Math.PI * 2 / 4) * j - Math.PI / 2;
            const x = centerX + Math.cos(angle) * (radius * i / 5);
            const y = centerY + Math.sin(angle) * (radius * i / 5);
            if (j === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
        }
        ctx.closePath();
        ctx.stroke();
    }

    // 绘制轴线
    ctx.strokeStyle = 'rgba(0, 212, 255, 0.5)';
    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.lineTo(
            centerX + Math.cos(angle) * radius,
            centerY + Math.sin(angle) * radius
        );
        ctx.stroke();
    }

    // 绘制属性值多边形
    ctx.fillStyle = 'rgba(138, 43, 226, 0.3)';
    ctx.strokeStyle = '#8a2be2';
    ctx.lineWidth = 2;
    ctx.beginPath();

    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        const value = attributes[i].value / attributes[i].max;
        const x = centerX + Math.cos(angle) * (radius * value);
        const y = centerY + Math.sin(angle) * (radius * value);
        if (i === 0) {
            ctx.moveTo(x, y);
        } else {
            ctx.lineTo(x, y);
        }
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // 绘制属性点
    ctx.fillStyle = '#00d4ff';
    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        const value = attributes[i].value / attributes[i].max;
        const x = centerX + Math.cos(angle) * (radius * value);
        const y = centerY + Math.sin(angle) * (radius * value);
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
    }

    // 绘制属性标签
    ctx.fillStyle = '#00d4ff';
    ctx.font = 'bold 14px Consolas';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    for (let i = 0; i < 4; i++) {
        const angle = (Math.PI * 2 / 4) * i - Math.PI / 2;
        const labelRadius = radius + 25;
        const x = centerX + Math.cos(angle) * labelRadius;
        const y = centerY + Math.sin(angle) * labelRadius;
        ctx.fillText(attributes[i].name, x, y);

        // 显示数值
        ctx.font = '12px Consolas';
        ctx.fillStyle = '#ffffff';
        const valueY = y + (i === 0 ? -15 : i === 2 ? 15 : 0);
        ctx.fillText(attributes[i].value, x, valueY);
        ctx.fillStyle = '#00d4ff';
        ctx.font = 'bold 14px Consolas';
    }
}

// 初始化
updateDisplay();

