        .post-item {
            background: rgba(0, 0, 0, 0.6);
            border: 1px solid rgba(0, 255, 204, 0.3);
            border-radius: 8px;
            padding: 15px;
            margin-bottom: 15px;
            cursor: pointer;
            transition: all 0.3s ease;
            position: relative;
            overflow: hidden;
        }

        .post-item::before {
            content: '';
            position: absolute;
            top: 0;
            left: -100%;
            width: 100%;
            height: 100%;
            background: linear-gradient(90deg, transparent, rgba(0, 255, 204, 0.1), transparent);
            transition: left 0.5s ease;
        }

        .post-item:hover::before {
            left: 100%;
        }

        .post-item:hover {
            border-color: #00ffcc;
            box-shadow: 0 0 15px rgba(0, 255, 204, 0.4);
            transform: translateX(5px);
        }

        .post-header-info {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 10px;
        }

        .post-title {
            font-size: 18px;
            color: #00ffcc;
            font-weight: 600;
        }

        .post-heat {
            font-size: 14px;
            color: #ff0080;
            display: flex;
            align-items: center;
            gap: 5px;
        }

        .post-preview {
            font-size: 14px;
            color: #999;
            margin-top: 8px;
            display: none;
        }

        .post-item.expanded .post-preview {
            display: block;
        }

        .comments-section {
            display: none;
            margin-top: 15px;
            padding-top: 15px;
            border-top: 1px solid rgba(0, 255, 204, 0.2);
            max-height: 300px;
            overflow-y: auto;
        }

        .comments-section::-webkit-scrollbar {
            width: 6px;
        }

        .comments-section::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.3);
        }

        .comments-section::-webkit-scrollbar-thumb {
            background: #00ffcc;
            border-radius: 3px;
        }

        .post-item.expanded .comments-section {
            display: block;
        }

        .comment {
            background: rgba(0, 255, 204, 0.05);
