            border-radius: 8px;
            border: 1px solid rgba(0, 255, 204, 0.3);
        }

        .post-item.expanded .input-section {
            display: block;
        }

        .forum-textarea {
            width: 100%;
            min-height: 60px;
            padding: 12px;
            background: rgba(0, 0, 0, 0.6);
            border: 1px solid rgba(0, 255, 204, 0.3);
            border-radius: 6px;
            color: #00ffcc;
            font-family: inherit;
            font-size: 14px;
            resize: vertical;
        }

        .forum-textarea:focus {
            outline: none;
            border-color: #00ffcc;
            box-shadow: 0 0 10px rgba(0, 255, 204, 0.3);
        }

        .button-group {
            display: flex;
            gap: 10px;
            margin-top: 10px;
            justify-content: flex-end;
        }

        .cyber-button {
            background: linear-gradient(135deg, rgba(0, 255, 204, 0.1) 0%, rgba(255, 0, 128, 0.1) 100%);
            border: 1px solid rgba(0, 255, 204, 0.5);
            color: #00ffcc;
            padding: 8px 20px;
            border-radius: 6px;
            cursor: pointer;
            font-family: inherit;
            font-size: 14px;
            transition: all 0.3s ease;
        }

        .cyber-button:hover {
            background: linear-gradient(135deg, rgba(0, 255, 204, 0.2) 0%, rgba(255, 0, 128, 0.2) 100%);
            box-shadow: 0 0 15px rgba(0, 255, 204, 0.5);
            transform: translateY(-2px);
        }

        .send-button {
            background: linear-gradient(135deg, #00ffcc 0%, #00ccff 100%);
            color: #0a0a0a;
            font-weight: 600;
            border: none;
        }

        .send-button:hover {
            background: linear-gradient(135deg, #00ffcc 0%, #ff0080 100%);
        }
    </style>
</head>
<body>
    <div class="forum-container">
        <div class="forum-header">
            <h1 class="forum-title">CYBER FORUM</h1>
            <div class="forum-subtitle">数据交流中心 · 信息枢纽</div>
        </div>

        <div class="posts-section">
            <!-- 帖子1 -->
            <div class="post-item" onclick="togglePost(this)">
                <div class="post-header-info">
                    <div class="post-title">$1</div>
                    <div class="post-heat">🔥 $2</div>
                </div>
                <div class="post-preview">点击查看详情...</div>
                <div class="comments-section">
                    <div id="comments-1">$3</div>
                </div>
                <div class="input-section">
                    <textarea class="forum-textarea" placeholder="输入您的评论..."></textarea>
                    <div class="button-group">
                        <button class="cyber-button" onclick="sendComment(this)">发送评论</button>
                        <button class="cyber-button send-button" onclick="sendToChat(this)">发送到聊天</button>
                    </div>
                </div>
            </div>

            <!-- 帖子2 -->
            <div class="post-item" onclick="togglePost(this)">
                <div class="post-header-info">
                    <div class="post-title">$4</div>
                    <div class="post-heat">🔥 $5</div>
                </div>
                <div class="post-preview">点击查看详情...</div>
                <div class="comments-section">
                    <div id="comments-2">$6</div>
                </div>
                <div class="input-section">
                    <textarea class="forum-textarea" placeholder="输入您的评论..."></textarea>
                    <div class="button-group">
                        <button class="cyber-button" onclick="sendComment(this)">发送评论</button>
                        <button class="cyber-button send-button" onclick="sendToChat(this)">发送到聊天</button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        // 处理评论格式
        function processComments() {
            for(let i = 1; i <= 2; i++) {
                const commentsDiv = document.getElementById('comments-' + i);
                if(commentsDiv) {
                    const content = commentsDiv.innerHTML.trim();
                    if(content && !content.includes('$')) {
                        const lines = content.split('\n').filter(line => line.trim());
                        let html = '';
                        lines.forEach(line => {
                            const match = line.match(/\[([^\]]+)\](.+)/);
                            if(match) {
                                html += `<div class="comment">
                                    <div class="comment-author">${match[1]}</div>
                                    <div class="comment-text">${match[2].trim()}</div>
                                </div>`;
                            }
                        });
                        if(html) {
                            commentsDiv.innerHTML = html;
                        } else if(!content || content === '') {
                            commentsDiv.innerHTML = '<div class="no-comments">暂无评论</div>';
                        }
                    } else if(content.includes('$')) {
                        commentsDiv.innerHTML = '<div class="no-comments">暂无评论</div>';
                    }
                }
            }
        }

        // 切换帖子展开/收起
        function togglePost(element) {
            event.stopPropagation();

            // 如果点击的是输入区域，不处理
            if(event.target.tagName === 'TEXTAREA' || event.target.tagName === 'BUTTON') {
                return;
            }

            // 关闭其他帖子
            document.querySelectorAll('.post-item').forEach(item => {
                if(item !== element) {
                    item.classList.remove('expanded');
                }
            });

            // 切换当前帖子
            element.classList.toggle('expanded');

            // 如果是第一次展开，处理评论
            if(element.classList.contains('expanded')) {
                processComments();
            }
        }

        // 发送评论
        function sendComment(button) {
            event.stopPropagation();
            const postItem = button.closest('.post-item');
            const textarea = postItem.querySelector('.forum-textarea');
            const message = textarea.value.trim();

            if(!message) {
                alert('请输入评论内容');
                return;
            }

            const commentsSection = postItem.querySelector('.comments-section > div');
            // 移除"暂无评论"提示
            const noComments = commentsSection.querySelector('.no-comments');
            if(noComments) {
                noComments.remove();
            }

            const newComment = document.createElement('div');
            newComment.className = 'comment';
            newComment.innerHTML = `
                <div class="comment-author">匿名用户</div>
                <div class="comment-text">${message}</div>
            `;
            commentsSection.appendChild(newComment);

            textarea.value = '';
        }

        // 发送到聊天
        function sendToChat(button) {
            event.stopPropagation();
            const postItem = button.closest('.post-item');
            const textarea = postItem.querySelector('.forum-textarea');
            const message = textarea.value.trim();

            if(!message) {
                alert('请输入内容');
                return;
            }

            const postTitle = postItem.querySelector('.post-title').textContent;
            const formattedMessage = `【论坛-${postTitle}】${message}`;

            navigator.clipboard.writeText(formattedMessage).then(() => {
                textarea.value = '';
                alert('消息已复制到剪贴板');
            }).catch(() => {
                alert('复制失败');
            });
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', function() {
            setTimeout(processComments, 100);
        });
    </script>
</body>
</html>
