    padding: 0;
}

.voice {
    font-size: 24px;
    color: #12B7F5;
    margin-left: 10px;
    transform: rotate(90deg);
    cursor: pointer;
}

/* @提及 */
.at {
    color: #576b95;
}

/* 表情 */
.em {
    font-size: 18px;
}
</style>
</head>
<body>

<div class="phone-container">
    <!-- 顶部 -->
    <div class="header">
        <span class="back">&lt;</span>
        <span class="title">$1</span>
        <span class="more">⋮</span>
    </div>

    <!-- 消息区 -->
    <div class="messages" id="messages">
        <div id="msgList">$3</div>
    </div>

    <!-- 输入区 -->
    <div class="footer">
        <span class="plus">+</span>
        <div class="input-wrapper">
            <input type="text" class="input" id="input" placeholder="">
        </div>
        <span class="voice">▷</span>
    </div>
</div>

<script>
// 成员数量
const members = '$2'.split('、').filter(m => m.trim());

// 初始化消息
function init() {
    const container = document.getElementById('msgList');
    const content = container.innerHTML.trim();

    if(content && !content.startsWith('$')) {
        const lines = content.split('\n').filter(line => line.trim());
        let html = '';
        let currentTime = new Date();

        lines.forEach((line, i) => {
            // 每5条消息显示时间
            if(i === 0 || i % 5 === 0) {
                const time = new Date(currentTime - (lines.length - i) * 60000);
                const timeStr = time.getHours().toString().padStart(2, '0') + ':' + 
                               time.getMinutes().toString().padStart(2, '0');
                html += `<div class="time">${timeStr}</div>`;
            }

            // 系统消息
            if(line.startsWith('[系统]')) {
                html += `<div class="sys"><span>${line.slice(4)}</span></div>`;
                return;
            }

            // 普通消息
            const match = line.match(/^\[([^\]]+)\](.+)/);
            if(match) {
                const author = match[1];
                const text = match[2].trim();
                const isMe = author === '你';

                html += `<div class="msg ${isMe ? 'me' : ''}">
                    <div class="avatar">${author[0]}</div>
                    <div class="content">
                        <div class="name">${author}</div>
                        <div class="bubble">${formatText(text)}</div>
                    </div>
                </div>`;
            }
        });

        container.innerHTML = html;
        scrollToBottom();
    }

    // 更新标题显示成员数
    document.querySelector('.title').innerHTML = `$1 <span style="color:#999;font-size:12px;">(${members.length})</span>`;
}

// 格式化文本
function formatText(text) {
    // @提及
    text = text.replace(/@(\S+)/g, '<span class="at">@$1</span>');

    // 表情
    const emojis = {
        ':)': '😊', ':D': '😄', ':(': '😢', ':P': '😛',
        ':o': '😮', ':|': '😐', ';)': '😉', '<3': '❤️',
        '[微笑]': '😊', '[撇嘴]': '😥', '[色]': '😍',
        '[发呆]': '😳', '[得意]': '😏', '[流泪]': '😭',
        '[害羞]': '😊', '[闭嘴]': '🤐', '[睡]': '😴',
        '[大哭]': '😭', '[尴尬]': '😅', '[发怒]': '😠',
        '[调皮]': '😜', '[呲牙]': '😁', '[惊讶]': '😮',
        '[难过]': '😔', '[酷]': '😎', '[冷汗]': '😰',
        '[抓狂]': '😤', '[吐]': '🤮', '[偷笑]': '🤭',
        '[可爱]': '😊', '[白眼]': '🙄', '[傲慢]': '😤',
        '[饥饿]': '😋', '[困]': '😪', '[惊恐]': '😱',
        '[流汗]': '😓', '[憨笑]': '😄', '[悠闲]': '😌',
        '[奋斗]': '💪', '[咒骂]': '🤬', '[疑问]': '🤔',
        '[嘘]': '🤫', '[晕]': '😵', '[疯了]': '🤪',
        '[衰]': '😣', '[骷髅]': '💀', '[敲打]': '🔨',
        '[再见]': '👋', '[擦汗]': '😅', '[抠鼻]': '🤧',
        '[鼓掌]': '👏', '[糗大了]': '😳', '[坏笑]': '😈',
        '[左哼哼]': '😤', '[右哼哼]': '😤', '[哈欠]': '🥱',
        '[鄙视]': '😒', '[委屈]': '😢', '[快哭了]': '😢',
        '[阴险]': '😈', '[亲亲]': '😘', '[吓]': '😱',
        '[可怜]': '🥺'
    };

    for(const [k, v] of Object.entries(emojis)) {
        text = text.replace(new RegExp(k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g'), 
            `<span class="em">${v}</span>`);
    }

    return text;
}

// 滚动到底部
function scrollToBottom() {
    const messages = document.getElementById('messages');
    messages.scrollTop = messages.scrollHeight;
}

// 发送消息
function sendMessage() {
    const input = document.getElementById('input');
    const text = input.value.trim();

    if(!text) return;

    const msgList = document.getElementById('msgList');
    const now = new Date();
    const timeStr = now.getHours().toString().padStart(2, '0') + ':' + 
                   now.getMinutes().toString().padStart(2, '0');

    // 检查是否需要添加时间
    const lastTime = msgList.querySelector('.time:last-child');
    if(!lastTime || msgList.children.length - Array.from(msgList.children).lastIndexOf(lastTime) > 5) {
        msgList.insertAdjacentHTML('beforeend', `<div class="time">${timeStr}</div>`);
    }

    // 添加消息
    msgList.insertAdjacentHTML('beforeend', `
        <div class="msg me">
            <div class="avatar">我</div>
            <div class="content">
                <div class="bubble">${formatText(text)}</div>
            </div>
        </div>
    `);

    input.value = '';
    scrollToBottom();
}

// 输入框回车发送
document.getElementById('input').addEventListener('keydown', function(e) {
    if(e.key === 'Enter') {
        e.preventDefault();
        sendMessage();
    }
});

// 初始化
init();
</script>

</body>
</html>
