    <script>
        // 处理榜单格式
        function processRankings() {
            const tianbang = document.getElementById('tianbang');
            const dibang = document.getElementById('dibang');

            [tianbang, dibang].forEach((board, index) => {
                if(board) {
                    const content = board.innerHTML.trim();
                    if(content && !content.includes('$')) {
                        const items = content.split('\n').filter(item => item.trim());
                        let html = '';
                        items.forEach((item, i) => {
                            html += `<div class="ranking-item">
                                <span class="ranking-number">第${i + 1}位：</span>${item.trim()}
                            </div>`;
                        });
                        board.innerHTML = html || '<div style="text-align:center;color:#8b4513;padding:20px;">暂无上榜高手</div>';
                    } else {
                        board.innerHTML = '<div style="text-align:center;color:#8b4513;padding:20px;">暂无上榜高手</div>';
                    }
                }
            });
        }

        // 处理留言格式
        function processMessages() {
            const messageBoard = document.getElementById('message-board');
            if(messageBoard) {
                const content = messageBoard.innerHTML.trim();
                if(content && !content.includes('$')) {
                    const lines = content.split('\n').filter(line => line.trim());
                    let html = '';
                    lines.forEach(line => {
                        const match = line.match(/\[([^\]]+)\](.+)/);
                        if(match) {
                            html += `<div class="message-item">
                                <div class="message-author">${match[1]}</div>
                                <div class="message-text">${match[2].trim()}</div>
                            </div>`;
                        }
                    });
                    messageBoard.innerHTML = html || '<div class="no-messages">暂无江湖留言</div>';
                } else {
                    messageBoard.innerHTML = '<div class="no-messages">暂无江湖留言</div>';
                }
            }
        }

        // 发布留言
        function postMessage() {
            const textarea = document.getElementById('message-input');
            const message = textarea.value.trim();

            if(!message) {
                alert('请输入留言内容');
                return;
            }

            const messageBoard = document.getElementById('message-board');
            const noMessages = messageBoard.querySelector('.no-messages');
            if(noMessages) {
                noMessages.remove();
            }

            const newMessage = document.createElement('div');
            newMessage.className = 'message-item';
            newMessage.innerHTML = `
                <div class="message-author">{{user}}</div>
                <div class="message-text">${message}</div>
            `;
            messageBoard.appendChild(newMessage);

            textarea.value = '';
            messageBoard.scrollTop = messageBoard.scrollHeight;
        }

        // 发送到聊天
        function sendToChat() {
            const textarea = document.getElementById('message-input');
            const message = textarea.value.trim();

            if(!message) {
                alert('请输入内容');
                return;
            }

            const formattedMessage = `【灵枢网留言】${message}`;

            navigator.clipboard.writeText(formattedMessage).then(() => {
                textarea.value = '';
                alert('消息已复制到剪贴板');
            }).catch(() => {
                alert('复制失败');
            });
        }

        // 初始化
        document.addEventListener('DOMContentLoaded', function() {
            setTimeout(() => {
                processRankings();
                processMessages();
            }, 100);
        });
    </script>
</body>
</html>
