}

.summary-label {
    color: #00ffff;
    font-size: clamp(14px, 3vw, 16px);
}

.summary-value {
    color: #fff;
    font-weight: bold;
    font-size: clamp(14px, 3vw, 16px);
    word-break: break-word;
}

.btn-group {
    display: flex;
    gap: 15px;
    justify-content: center;
    flex-wrap: wrap;
    margin-top: 20px;
}

.btn {
    padding: 12px 30px;
    background: linear-gradient(135deg, #00ffff 0%, #ff8800 100%);
    border: none;
    border-radius: 10px;
    color: #000;
    font-size: clamp(14px, 3vw, 18px);
    font-weight: bold;
