    gap: 12px;
    margin-top: 12px;
}

.currency-item {
    background: rgba(0, 255, 255, 0.1);
    border: 1px solid rgba(0, 255, 255, 0.3);
    border-radius: 10px;
    padding: 12px;
}

.currency-name {
    color: #ff8800;
    font-weight: bold;
    margin-bottom: 5px;
    font-size: clamp(14px, 3vw, 16px);
}

.currency-desc {
    font-size: clamp(12px, 2.8vw, 14px);
    color: #ccc;
}

.custom-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 15px;
}

.custom-section {
    background: rgba(0, 255, 255, 0.05);
    border: 1px solid rgba(0, 255, 255, 0.2);
    border-radius: 10px;
    padding: 15px;
