/* 移动端特殊优化 */
@media (max-width: 768px) {
    body {
        padding: 0;
    }

    .container {
        border-radius: 0;
        min-height: 100vh;
        padding: 15px;
    }

    .cover-content {
        width: 85%;
        padding: 25px 15px;
    }

    .race-grid {
        grid-template-columns: 1fr;
    }

    .realm-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .attr-item {
        padding: 10px;
    }

    .attr-desc {
        width: 100%;
        text-align: left;
        font-size: 12px;
    }

    pre {
        font-size: 10px;
        overflow-x: auto;
    }

    /* 优化滚动 */
    .intro-text, .final-output {
        -webkit-overflow-scrolling: touch;
    }

    /* 防止双击缩放 */
    * {
        touch-action: manipulation;
    }
}

/* 横屏优化 */
@media (orientation: landscape) and (max-height: 500px) {
    .cover-content {
        padding: 20px;
    }

    .cover-title {
        font-size: 36px;
    }

    .cover-description {
        display: none;
    }

    .header {
        margin-bottom: 15px;
    }

    .section-title {
        margin-bottom: 15px;
    }
}

/* 修复iOS输入框问题 */
@supports (-webkit-touch-callout: none) {
    .input, .textarea {
        font-size: 16px;
    }
}

/* 滚动条美化 */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}

::-webkit-scrollbar-track {
    background: rgba(0, 255, 255, 0.1);
    border-radius: 3px;
}

::-webkit-scrollbar-thumb {
    background: rgba(0, 255, 255, 0.5);
    border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(0, 255, 255, 0.7);
}
