                    <textarea class="textarea" id="mechaNonCombat" placeholder="描述机甲的非战斗形态..."></textarea>
                </div>
            </div>

            <div class="custom-section">
                <div class="custom-title">开局设定</div>
                <div class="input-group">
                    <label class="label">开局故事</label>
                    <textarea class="textarea" id="startingStory" placeholder="描述角色的开局情况..." style="min-height: 150px;"></textarea>
                </div>
            </div>
        </div>

        <div class="btn-group">
            <button class="btn btn-secondary" onclick="prevPage()">上一页</button>
            <button class="btn" onclick="nextPage()">下一页</button>
        </div>
    </div>

    <!-- 第9页：确认信息 -->
    <div id="page9" class="page">
        <h2 class="section-title">确认角色信息</h2>

        <div class="summary">
            <div class="summary-item">
                <span class="summary-label">名字</span>
                <span class="summary-value" id="summaryName">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">年龄</span>
                <span class="summary-value" id="summaryAge">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">种族</span>
                <span class="summary-value" id="summaryRace">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">职业</span>
                <span class="summary-value" id="summaryProfession">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">属性</span>
                <span class="summary-value" id="summaryAttributes">-</span>
            </div>
        </div>

        <div class="btn-group">
            <button class="btn btn-secondary" onclick="prevPage()">上一页</button>
            <button class="btn" onclick="generateCharacter()">生成角色</button>
        </div>
    </div>

    <!-- 第10页：最终输出 -->
    <div id="page10" class="page">
        <h2 class="section-title">角色创建完成</h2>

        <div class="final-output" id="finalOutput"></div>

        <div class="btn-group">
            <button class="btn btn-secondary" onclick="location.reload()">创建新角色</button>
            <button class="btn" onclick="copyToClipboard()">复制角色信息</button>
        </div>
    </div>
</div>

<script>
let currentPage = 1;
const totalPages = 10;
let selectedRace = '';
let attributes = {
    yi: 0,
    ling: 0,
    agi: 0,
    ac: 0
};
let remainingPoints = 20;

// 开始创建角色
function startCreation() {
    // 淡出封面
    const coverPage = document.getElementById('coverPage');
    coverPage.style.transition = 'opacity 0.5s ease';
    coverPage.style.opacity = '0';

    setTimeout(() => {
        coverPage.style.display = 'none';
        document.getElementById('mainContainer').style.display = 'block';
        updateProgress();
    }, 500);
}

function updateProgress() {
    const progress = document.getElementById('progress');
    progress.style.width = `${(currentPage / totalPages) * 100}%`;
}

function showPage(pageNum) {
    document.querySelectorAll('.page').forEach(page => {
        page.classList.remove('active');
    });
    document.getElementById(`page${pageNum}`).classList.add('active');
    updateProgress();
}

function nextPage() {
    if (currentPage < totalPages) {
        // 验证当前页面
        if (!validateCurrentPage()) {
            return;
        }
        currentPage++;
        showPage(currentPage);

        // 如果到达确认页面，更新摘要
        if (currentPage === 9) {
            updateSummary();
        }
    }
}

function prevPage() {
    if (currentPage > 1) {
        currentPage--;
        showPage(currentPage);
    }
}

function validateCurrentPage() {
    switch(currentPage) {
        case 6: // 种族选择页
            if (!selectedRace) {
                alert('请选择一个种族！');
                return false;
            }
            break;

        case 7: // 属性分配页
            if (remainingPoints > 0) {
                alert('请分配所有属性点！');
                return false;
            }
            break;

        case 8: // 自定义信息页
            const name = document.getElementById('name').value;
            const age = document.getElementById('age').value;

            if (!name || !age) {
                alert('请至少填写名字和年龄！');
                return false;
            }
            break;
    }
    return true;
}

function selectRace(race) {
    selectedRace = race;
    document.querySelectorAll('.race-card').forEach(card => {
        card.classList.remove('selected');
    });
    event.currentTarget.classList.add('selected');

    // 重置属性点
    attributes = {
        yi: 0,
        ling: 0,
        agi: 0,
        ac: 0
    };
    remainingPoints = 20;

    // 应用种族加成
    switch(race) {
        case '人类':
            attributes.yi += 2;
            attributes.ling += 2;
            break;
        case '精灵':
            attributes.agi += 2;
            attributes.ling += 2;
            break;
        case '矮人':
            attributes.ac += 2;
            attributes.ling += 2;
            break;
        case '兽人':
            attributes.yi += 2;
            attributes.ling += 2;
            attributes.agi += 2;
            break;
        case '龙裔':
            attributes.yi += 3;
            attributes.ling += 3;
            attributes.agi += 3;
            break;
        case '巨人':
            attributes.yi += 5;
            break;
    }

    // 更新显示
    updateAttributeDisplay();
}

function adjustAttribute(attr, delta) {
    if (delta > 0 && remainingPoints <= 0) return;
    if (delta < 0 && attributes[attr] <= 0) return;

    attributes[attr] += delta;
    remainingPoints -= delta;

    updateAttributeDisplay();
}

function updateAttributeDisplay() {
    document.getElementById('yiValue').textContent = attributes.yi;
    document.getElementById('lingValue').textContent = attributes.ling;
    document.getElementById('agiValue').textContent = attributes.agi;
    document.getElementById('acValue').textContent = attributes.ac;
    document.getElementById('remainingPoints').textContent = remainingPoints;

    // 更新按钮状态
    updateAttributeButtons();
}

function updateAttributeButtons() {
    const buttons = document.querySelectorAll('.attr-btn');
    buttons.forEach(btn => {
        btn.disabled = false;
    });

    if (remainingPoints <= 0) {
        buttons.forEach(btn => {
            if (btn.textContent === '+') {
                btn.disabled = true;
            }
        });
    }
}

function updateSummary() {
    document.getElementById('summaryName').textContent = document.getElementById('name').value || '-';
    document.getElementById('summaryAge').textContent = document.getElementById('age').value || '-';
    document.getElementById('summaryRace').textContent = selectedRace || '-';
    document.getElementById('summaryProfession').textContent = document.getElementById('profession').value || '-';
    document.getElementById('summaryAttributes').textContent = 
        `意:${attributes.yi} 灵:${attributes.ling} 敏捷:${attributes.agi} AC:${attributes.ac}`;
}

function generateCharacter() {
    const name = document.getElementById('name').value;
    const age = document.getElementById('age').value;
    const identity = document.getElementById('identity').value || '未设定';
    const profession = document.getElementById('profession').value || '未设定';
    const appearance = document.getElementById('appearance').value || '未设定';
    const background = document.getElementById('background').value || '未设定';
    const items = document.getElementById('items').value || '无';
    const bag = document.getElementById('bag').value || '空';
    const assets = document.getElementById('assets').value || '无';
    const mechaInfo = document.getElementById('mechaInfo').value || '无';
    const mechaAppearance = document.getElementById('mechaAppearance').value || '无';
    const mechaWeapons = document.getElementById('mechaWeapons').value || '无';
    const mechaModules = document.getElementById('mechaModules').value || '无';
    const mechaNonCombat = document.getElementById('mechaNonCombat').value || '无';
    const startingStory = document.getElementById('startingStory').value || '未设定';

    const output = `【灵纪元2025 - 角色档案】

名字：${name}
年龄：${age}
种族：${selectedRace}
身份：${identity}
职业：${profession}
境界：一阶
经验值：0/15

【属性】
意：${attributes.yi}
灵：${attributes.ling}
敏捷：${attributes.agi}
AC：${attributes.ac}

【状态】
生命值：60/60

【外貌】
${appearance}

【背景故事】
${background}

【道具】
${items}

【包】
${bag}

【资产】
${assets}

【机甲信息】
${mechaInfo}

【机甲外貌】
${mechaAppearance}

【机甲武器】
${mechaWeapons}

【机甲模组】
${mechaModules}

【机甲非战斗形态】
${mechaNonCombat}

【开局故事】
${startingStory}`;

    document.getElementById('finalOutput').textContent = output;
    currentPage = 10;
    showPage(currentPage);
}

function copyToClipboard() {
    const output = document.getElementById('finalOutput').textContent;
    navigator.clipboard.writeText(output).then(() => {
        alert('角色信息已复制到剪贴板！');
    });
}

// 初始化
updateProgress();
// 添加触摸事件支持
document.addEventListener('DOMContentLoaded', function() {
    // 防止iOS橡皮筋效果
    document.body.addEventListener('touchmove', function(e) {
        if (!e.target.closest('.intro-text, .final-output, .textarea')) {
            e.preventDefault();
        }
    }, { passive: false });

    // 优化按钮点击
    const buttons = document.querySelectorAll('.btn, .attr-btn, .race-card');
    buttons.forEach(btn => {
        btn.addEventListener('touchstart', function() {
            this.style.transform = 'scale(0.95)';
        });
        btn.addEventListener('touchend', function() {
            this.style.transform = '';
        });
    });
});
</script>

</body>
</html>
