    border: 1px solid rgba(138,43,226,0.3);
    border-radius: 8px;
    padding: 15px;
    margin-bottom: 20px;
}

.mecha-title {
    color: #8a2be2;
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 10px;
}

.mecha-info {
    color: #ffffff;
    font-size: 14px;
    line-height: 1.6;
    white-space: pre-wrap;
}

/* 四维图样式 */
.radar-container {
    width: 300px;
    height: 300px;
    margin: 20px auto;
    position: relative;
}

.attr-list {
    margin-bottom: 20px;
}

.attr-header {
    text-align: center;
    margin-bottom: 20px;
    padding-bottom: 15px;
    border-bottom: 1px solid rgba(0,212,255,0.3);
}

.points-display {
    color: #8a2be2;
    font-size: 24px;
    font-weight: bold;
}

.attr-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px;
    background: rgba(0,212,255,0.05);
    border: 1px solid rgba(0,212,255,0.2);
    border-radius: 6px;
    margin-bottom: 10px;
}

.attr-name {
    color: #00d4ff;
    font-size: 15px;
    width: 60px;
}

.attr-value {
    color: #ffffff;
    font-size: 20px;
    font-weight: bold;
    margin: 0 15px;
}

.attr-btn {
    width: 32px;
    height: 32px;
    background: linear-gradient(135deg, #00d4ff 0%, #00a8cc 100%);
    border: none;
    border-radius: 50%;
    color: #0a0a0a;
    font-size: 18px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
}

.attr-btn:hover:not(:disabled) {
    transform: scale(1.15);
    box-shadow: 0 0 20px rgba(0,212,255,0.8);
}

.attr-btn:disabled {
    opacity: 0.3;
    cursor: not-allowed;
}

/* 属性评价样式 */
.attr-evaluation {
    color: #8a2be2;
    font-size: 12px;
    font-style: italic;
    margin-left: 10px;
}

/* 属性分配指令区域 */
.command-area {
    margin-top: 20px;
    padding-top: 20px;
    border-top: 1px solid rgba(0,212,255,0.3);
}

.command-textarea {
    width: 100%;
    height: 60px !important;
    min-height: 60px !important;
    max-height: 60px !important;
    background: rgba(0,0,0,0.8);
    border: 1px solid rgba(0,212,255,0.5);
    border-radius: 6px;
    color: #00d4ff;
    padding: 10px;
    font-family: inherit;
    font-size: 13px;
    resize: none !important;
    overflow-y: auto;
}

.command-buttons {
    display: flex;
    gap: 10px;
    margin-top: 10px;
}

.cmd-btn {
    flex: 1;
    padding: 8px 16px;
    background: linear-gradient(135deg, rgba(0,212,255,0.2) 0%, rgba(138,43,226,0.2) 100%);
    border: 1px solid rgba(0,212,255,0.5);
    border-radius: 6px;
    color: #00d4ff;
    font-size: 13px;
    font-weight: bold;
    cursor: pointer;
    transition: all 0.3s ease;
    text-transform: uppercase;
}

.cmd-btn:hover {
    background: linear-gradient(135deg, rgba(0,212,255,0.3) 0%, rgba(138,43,226,0.3) 100%);
    box-shadow: 0 5px 15px rgba(0,212,255,0.5);
}

/* 装备详情样式 */
.equip-section {
    margin-bottom: 20px;
}

.equip-title {
    color: #8a2be2;
    font-size: 16px;
    font-weight: bold;
    margin-bottom: 10px;
}

.equip-item {
    background: rgba(0,0,0,0.4);
    border: 1px solid rgba(0,212,255,0.2);
    border-radius: 6px;
    padding: 10px;
    margin-bottom: 8px;
    white-space: pre-wrap;
}

/* 手机端响应式设计 */
@media (max-width: 768px) {
    body {
        padding: 5px;
    }

    .main-container {
        width: 100%;
    }

    .nav-btn {
        min-width: 80px;
        font-size: 12px;
        padding: 8px 12px;
    }

    .nav-btn span:first-child {
        display: none;
    }

    .page {
        padding: 15px;
        border-radius: 8px;
    }

    .dialog-content {
        font-size: 14px;
        padding: 15px;
    }

    .map-title {
        font-size: 18px;
    }

    .continent-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 8px;
    }

    .continent-card {
        padding: 12px;
    }

    .continent-name {
        font-size: 16px;
    }

    .info-grid {
        grid-template-columns: 1fr;
        gap: 8px;
    }

    .char-name {
        font-size: 24px;
    }

    .tab-btn {
        font-size: 11px;
        padding: 6px 10px;
    }

    .radar-container {
        width: 250px;
        height: 250px;
    }

    .attr-item {
        padding: 10px;
    }

    .attr-name {
        font-size: 14px;
        width: 50px;
    }

    .attr-value {
        font-size: 18px;
        margin: 0 10px;
    }

    .attr-btn {
        width: 28px;
        height: 28px;
        font-size: 16px;
    }

    .command-textarea {
        font-size: 12px;
        height: 50px !important;
        min-height: 50px !important;
        max-height: 50px !important;
    }

    .cmd-btn {
        font-size: 12px;
        padding: 6px 12px;
    }
}

@media (max-width: 480px) {
    .continent-grid {
        grid-template-columns: 1fr;
    }

    .dialog-content {
        font-size: 13px;
        padding: 12px;
    }

    .radar-container {
        width: 200px;
        height: 200px;
    }

    .attr-item {
        flex-wrap: wrap;
        justify-content: center;
        text-align: center;
    }

    .attr-name {
        width: 100%;
        margin-bottom: 5px;
    }

    .attr-value {
        order: -1;
        width: 100%;
        margin: 5px 0;
    }

    .attr-evaluation {
        width: 100%;
        text-align: center;
        margin: 5px 0 0 0;
    }
}

/* 防止横向滚动 */
html, body {
    overflow-x: hidden;
}

/* 触摸设备优化 */
@media (hover: none) {
    .nav-btn:hover,
    .continent-card:hover,
    .tab-btn:hover,
    .attr-btn:hover:not(:disabled),
    .cmd-btn:hover {
        transform: none;
        box-shadow: none;
    }

    .nav-btn:active,
    .continent-card:active,
    .tab-btn:active,
    .attr-btn:active:not(:disabled),
    .cmd-btn:active {
        transform: scale(0.95);
    }
}
