        <div class="bar-container">
            <div class="bar-fill hp" style="width: $25%">
                <span class="bar-text">$25 / $26</span>
            </div>
        </div>
    </div>

    <div class="mecha-section">
        <div class="mecha-title">装载模组</div>
        <div class="mecha-info">$27</div>
    </div>

    <div class="mecha-section">
