// Tab切换
function showTab(tabNum) {
    // 隐藏所有tab内容
    const tabs = document.querySelectorAll('.tab-content');
    tabs.forEach(tab => tab.classList.remove('active'));

    // 显示选中的tab
    document.getElementById('tab-content-' + tabNum).classList.add('active');

    // 更新tab按钮状态
    const tabBtns = document.querySelectorAll('.tab-btn');
    tabBtns.forEach(btn => btn.classList.remove('active'));
    tabBtns[tabNum - 1].classList.add('active');
}

// 计算百分比
function calculatePercentage(current, max) {
    if (!current || !max || max === 0) return 0;
    return Math.min(100, Math.max(0, (current / max) * 100));
}

// 页面加载时更新进度条
window.addEventListener('DOMContentLoaded', function() {
    // 更新经验值进度条
    const expCurrent = parseInt('$12') || 0;
    const expMax = parseInt('$13') || 100;
    const expBar = document.querySelector('.bar-fill.exp');
    if (expBar) {
        expBar.style.width = calculatePercentage(expCurrent, expMax) + '%';
    }

    // 更新灵力值进度条
    const qiCurrent = parseInt('$14') || 0;
    const qiMax = parseInt('$15') || 100;
    const qiBar = document.querySelector('.bar-fill.qi');
    if (qiBar) {
        qiBar.style.width = calculatePercentage(qiCurrent, qiMax) + '%';
    }

    // 更新机甲生命值进度条
    const mechaCurrent = parseInt('$24') || 0;
    const mechaMax = parseInt('$25') || 100;
    const mechaBar = document.querySelector('#tab-content-4 .bar-fill.hp');
    if (mechaBar) {
        mechaBar.style.width = calculatePercentage(mechaCurrent, mechaMax) + '%';
    }
});

// 防止双击缩放
let lastTouchEnd = 0;
document.addEventListener('touchend', function (event) {
    const now = (new Date()).getTime();
    if (now - lastTouchEnd <= 300) {
        event.preventDefault();
    }
    lastTouchEnd = now;
}, false);
</script>

</body>
</html>
