    <!-- 第8页：自定义信息 -->
    <div id="page8" class="page">
        <h2 class="section-title">角色自定义</h2>

        <div class="custom-grid">
            <div class="custom-section">
                <div class="custom-title">基本信息</div>
                <div class="input-group">
                    <label class="label">名字</label>
                    <input type="text" class="input" id="name" placeholder="请输入角色名字">
                </div>

                <div class="input-group">
                    <label class="label">年龄</label>
                    <input type="text" class="input" id="age" placeholder="请输入年龄">
                </div>

                <div class="input-group">
                    <label class="label">身份</label>
                    <input type="text" class="input" id="identity" placeholder="例如：帝国学院学生、佣兵、商人等">
                </div>

                <div class="input-group">
                    <label class="label">职业</label>
                    <input type="text" class="input" id="profession" placeholder="例如：灵机使、机甲维修师、灵力研究员等">
                </div>
            </div>

            <div class="custom-section">
                <div class="custom-title">角色描述</div>
