            </div>
            <div class="summary-item">
                <span class="summary-label">年龄</span>
                <span class="summary-value" id="summaryAge">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">种族</span>
                <span class="summary-value" id="summaryRace">-</span>
            </div>
            <div class="summary-item">
                <span class="summary-label">职业</span>
                <span class="summary-value" id="summaryProfession">-</span>
            </div>
